package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;
import io.knowledgebrain.contracts.learning.evidencesession.v1.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class EvidenceSessionKafkaIntegrationTest extends EvidenceSessionFixtures {
 @Test void exactCommittedLinkRepinAndUnlinkSnapshotsTraceAndStableIdsReachKafka()throws Exception{init();var evidence=evidence("NOTE");var session=session(node);var first=link(evidence,"NOTE",session,0);var changed=study.changeSession(space,roadmap,session.sessionId(),actor,1,new LearningStudyStore.Input(node,session.startedAt(),Instant.parse(session.endedAt()).plusSeconds(600).toString(),"Changed session"),false,trace);link(evidence,"NOTE",changed,1);links.change(space,roadmap,evidence,"NOTE",actor,2,new EvidenceSessionStore.Input(null,null),trace);
  var expected=new HashMap<String,byte[]>();sql.query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,i)->{expected.put(rs.getObject(1,UUID.class).toString(),rs.getBytes(2));return 0;},first.linkId());assertEquals(3,expected.size());var options=new LearningStudyKafkaIntegrationTest().options();options.put("group.id","learning-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());
  try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("learning.evidence-session.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long end=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<3&&System.nanoTime()<end)for(var record:consumer.poll(Duration.ofSeconds(1))){if(!record.key().equals(first.linkId().toString()))continue;var envelope=EvidenceSessionEventEnvelopeV1.parseFrom(record.value());var payload=EvidenceSessionChangedPayloadV1.parseFrom(envelope.getPayload());assertArrayEquals(expected.get(envelope.getEventId()),record.value());assertEquals("EvidenceStudySessionChanged",envelope.getEventType());assertEquals("EvidenceStudySession",envelope.getAggregateType());assertEquals("learning-service",envelope.getProducer());assertEquals(actor.toString(),envelope.getActorId());assertEquals(space.toString(),envelope.getSpaceId());assertEquals(trace,envelope.getTraceId());assertEquals(first.linkId().toString(),payload.getLinkId());assertEquals(evidence.toString(),payload.getEvidenceId());assertEquals("NOTE",payload.getEvidenceKind());assertEquals(roadmap.toString(),payload.getRoadmapId());assertEquals(node.toString(),payload.getNodeId());assertEquals("A",payload.getNodeTitle());assertEquals("PRIVATE",payload.getVisibility());assertEquals(payload.getVersion()==3?"UNLINKED":"LINKED",payload.getState());if(payload.getVersion()==3){assertEquals("",payload.getSessionId());assertEquals(0,payload.getSessionVersion());assertEquals("",payload.getStartedAt());assertEquals(0,payload.getDurationSeconds());}else{assertEquals(session.sessionId().toString(),payload.getSessionId());assertEquals(payload.getVersion(),payload.getSessionVersion());assertEquals(session.startedAt(),payload.getStartedAt());assertEquals(payload.getVersion()==1?session.endedAt():changed.endedAt(),payload.getEndedAt());assertEquals(payload.getVersion()==1?session.durationSeconds():changed.durationSeconds(),payload.getDurationSeconds());}assertEquals(7,UUID.fromString(envelope.getEventId()).version());assertEquals(7,UUID.fromString(payload.getRevisionId()).version());for(var header:Map.of("trace_id",trace,"schema_group","learning","schema_artifact","evidence-session-events","schema_version","1").entrySet()){var actual=record.headers().lastHeader(header.getKey());assertNotNull(actual);assertEquals(header.getValue(),new String(actual.value(),StandardCharsets.UTF_8));}if(found.add(envelope.getEventId()))versions.add(payload.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions);}
 }
}
